import { useEffect, useState } from "react";
import { toast } from "react-toastify";

function AdminDashboard() {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5001/admin/stats", {
        headers: {
          Authorization: "Bearer " + token,
        },
      });

      const result = await response.json();

      if (response.ok) {
        setData(result);
      } else {
        toast.error(result.message);
      }
    } catch (error) {
      console.error(error);
      toast.error("Error fetching stats");
    }
  };

  if (!data) return <p>Loading...</p>;

  return (
    <div>
      <h2>Admin Dashboard</h2>

      <div className="admin-cards">
        <div className="admin-card">
          <h3>Total Faculties</h3>
          <p>{data.stats.total_faculties}</p>
        </div>

        <div className="admin-card">
          <h3>Total Feedback</h3>
          <p>{data.stats.total_feedback}</p>
        </div>

        <div className="admin-card">
          <h3>Average Rating</h3>
          <p>{data.stats.avg_rating} ⭐</p>
        </div>
      </div>

      <div className="admin-insights">
        <h3>Top Rated Faculty</h3>
        <p>
          {data.topRated?.name} ({data.topRated?.avg_rating} ⭐)
        </p>

        <h3>Most Reviewed Faculty</h3>
        <p>
          {data.mostReviewed?.name} ({data.mostReviewed?.total_reviews} reviews)
        </p>
      </div>
    </div>
  );
}

export default AdminDashboard;
